import 'package:flutter/material.dart';import 'package:intl/intl.dart';
import '../app.dart';import '../models/money_transaction.dart';import '../models/region_profile.dart';import '../services/local_store.dart';import 'add_transaction_page.dart';
class CategoryPage extends StatelessWidget{final LocalStore store;final RegionProfile profile;final String category;const CategoryPage({super.key,required this.store,required this.profile,required this.category});
 @override Widget build(BuildContext context){return AnimatedBuilder(animation:store,builder:(context,_){final now=DateTime.now();final items=store.transactions.where((t)=>t.type==MoneyTransactionType.expense&&t.category==category&&t.date.year==now.year&&t.date.month==now.month).toList();final total=items.fold(0.0,(s,t)=>s+t.amount);return Scaffold(appBar:AppBar(title:Text(category)),floatingActionButton:FloatingActionButton.extended(backgroundColor:kNeviroGreen,foregroundColor:Colors.white,onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>AddTransactionPage(store:store,profile:profile,type:MoneyTransactionType.expense,initialCategory:category))),icon:const Icon(Icons.add),label:Text('Add $category')),body:ListView(padding:const EdgeInsets.all(18),children:[Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('This Month',style:TextStyle(color:kNeviroMuted)),const SizedBox(height:4),Text(money(store,profile,total),style:const TextStyle(fontSize:28,fontWeight:FontWeight.w900))]))),const SizedBox(height:12),if(items.isEmpty)const Padding(padding:EdgeInsets.all(30),child:Center(child:Text('No transactions yet.'))),...items.map((t)=>Card(child:ListTile(title:Text(t.description.isEmpty?category:t.description),subtitle:Text(DateFormat('dd MMM yyyy').format(t.date)),trailing:Row(mainAxisSize:MainAxisSize.min,children:[Text(money(store,profile,t.amount),style:const TextStyle(fontWeight:FontWeight.w800)),IconButton(icon:const Icon(Icons.delete_outline),onPressed:()=>store.deleteTransaction(t.id))]))))]));});}}
